input.newString:
	/*
	 * LZ4 inplace decompression requires the compressed data to
	 * be arranged at the end of the decompressed buffer, so it can
	 * only be used if the input pages are exactly the last input
	 * pages of the output.  Otherwise, copy the compressed data
	 * instead of mapping a second, unordered buffer.
	 */
	for (i = 0; i < nrpages_in; ++i)
		if (rq->out[nrpages_out - nrpages_in + i] !=
		    rq->in[i])
			goto docopy;

	kunmap_atomic(inpage);
	*maptype = 3;
	return out + ((nrpages_out - nrpages_in) << PAGE_SHIFT);
}

