/*
 * Standalone logic harness for the ported EROFS LZ4 in-place decision.
 * It mirrors the modified decision of fs/erofs/decompressor.c
 * (z_erofs_handle_inplace_io) to exercise positive/negative paths.
 *
 * This is NOT a kernel build: it only validates the decision/offset logic.
 */
#include <stdio.h>
#include <stdbool.h>
#include <stdint.h>
#include <string.h>

#define PAGE_SHIFT 12
#define PAGE_SIZE (1u << PAGE_SHIFT)
#define PAGE_ALIGN(x) (((x) + PAGE_SIZE - 1) & ~(PAGE_SIZE - 1))
#define LZ4_DECOMPRESS_INPLACE_MARGIN(srcsize) (((srcsize) >> 8) + 32)

struct req {
	void *in[16], *out[16];
	unsigned short pageofs_out;
	unsigned int inputsize, outputsize;
	bool inplace_io, partial_decoding;
};

/* returns maptype; src out-param mirrors the returned pointer */
static int handle(const struct req *rq, void *inpage, void *out,
		  bool support_0padding, void **src_out)
{
	unsigned int nrpages_in, nrpages_out, ofull, oend, inputsize, i;

	inputsize = rq->inputsize;
	nrpages_in = PAGE_ALIGN(inputsize) >> PAGE_SHIFT;
	oend = rq->pageofs_out + rq->outputsize;
	ofull = PAGE_ALIGN(oend);
	nrpages_out = ofull >> PAGE_SHIFT;

