157: 	}
158: 	kunmap_atomic(inpage);
159: 	might_sleep();
160: 	src = erofs_vm_map_ram(rq->in, nrpages_in);
161: 	if (!src)
162: 		return ERR_PTR(-ENOMEM);
163: 	*maptype = 1;
164: 	return src;
