182: 		if (!inpage)
183: 			inpage = kmap_atomic(*in);
184: 		memcpy(tmp, inpage + *inputmargin, page_copycnt);
185: 		kunmap_atomic(inpage);
186: 		inpage = NULL;
187: 		tmp += page_copycnt;
188: 		total -= page_copycnt;
189: 		++in;
190: 		*inputmargin = 0;
191: 	}
