126: static void *z_erofs_handle_inplace_io(struct z_erofs_decompress_req *rq,
127: 			void *inpage, void *out, unsigned int *inputmargin,
128: 			int *maptype, bool support_0padding)
129: {
130: 	unsigned int nrpages_in, nrpages_out;
131: 	unsigned int ofull, oend, inputsize, total, i;
132: 	struct page **in;
133: 	void *src, *tmp;
134: 
135: 	inputsize = rq->inputsize;
136: 	nrpages_in = PAGE_ALIGN(inputsize) >> PAGE_SHIFT;
137: 	oend = rq->pageofs_out + rq->outputsize;
138: 	ofull = PAGE_ALIGN(oend);
139: 	nrpages_out = ofull >> PAGE_SHIFT;
140: 
141: 	if (rq->inplace_io) {
142: 		if (rq->partial_decoding || !support_0padding ||
143: 		    ofull - oend < LZ4_DECOMPRESS_INPLACE_MARGIN(inputsize))
144: 			goto docopy;
145: 
146: 		for (i = 0; i < nrpages_in; ++i)
147: 			if (rq->out[nrpages_out - nrpages_in + i] !=
148: 			    rq->in[i])
149: 				goto docopy;
150: 
151: 		kunmap_atomic(inpage);
152: 		*maptype = 3;
153: 		return out + ((nrpages_out - nrpages_in) << PAGE_SHIFT);
154: 	}
155: 
156: 	if (nrpages_in <= 1) {
157: 		*maptype = 0;
158: 		return inpage;
159: 	}
160: 	kunmap_atomic(inpage);
161: 	src = erofs_vm_map_ram(rq->in, nrpages_in);
162: 	if (!src)
163: 		return ERR_PTR(-ENOMEM);
164: 	*maptype = 1;
165: 	return src;
166: 
167: docopy:
168: 	/* Or copy compressed data which can be overlapped to per-CPU buffer */
169: 	in = rq->in;
170: 	src = erofs_get_pcpubuf(nrpages_in);
171: 	if (!src) {
172: 		DBG_BUGON(1);
173: 		kunmap_atomic(inpage);
174: 		return ERR_PTR(-EFAULT);
175: 	}
176: 
177: 	tmp = src;
178: 	total = rq->inputsize;
179: 	while (total) {
180: 		unsigned int page_copycnt =
181: 			min_t(unsigned int, total, PAGE_SIZE - *inputmargin);
182: 
183: 		if (!inpage)
184: 			inpage = kmap_atomic(*in);
185: 		memcpy(tmp, inpage + *inputmargin, page_copycnt);
186: 		kunmap_atomic(inpage);
187: 		inpage = NULL;
188: 		tmp += page_copycnt;
189: 		total -= page_copycnt;
190: 		++in;
191: 		*inputmargin = 0;
192: 	}
193: 	*maptype = 2;
194: 	return src;
195: }
