197: static int z_erofs_lz4_decompress(struct z_erofs_decompress_req *rq, u8 *out)
198: {
199: 	unsigned int inputmargin;
200: 	u8 *headpage, *src;
201: 	bool support_0padding;
202: 	int ret, maptype;
203: 
204: 	DBG_BUGON(*rq->in == NULL);
205: 	headpage = kmap_atomic(*rq->in);
206: 	inputmargin = 0;
207: 	support_0padding = false;
208: 
209: 	/* decompression inplace is only safe when 0padding is enabled */
210: 	if (erofs_sb_has_lz4_0padding(EROFS_SB(rq->sb))) {
211: 		support_0padding = true;
212: 
213: 		while (!headpage[inputmargin & ~PAGE_MASK])
214: 			if (!(++inputmargin & ~PAGE_MASK))
215: 				break;
216: 
217: 		if (inputmargin >= rq->inputsize) {
218: 			kunmap_atomic(headpage);
219: 			return -EIO;
220: 		}
221: 	}
222: 
223: 	rq->inputsize -= inputmargin;
224: 	src = z_erofs_handle_inplace_io(rq, headpage, out - rq->pageofs_out,
225: 					&inputmargin, &maptype,
226: 					support_0padding);
227: 	if (IS_ERR(src))
228: 		return PTR_ERR(src);
229: 
230: 	/* legacy format could compress extra data in a pcluster. */
231: 	if (rq->partial_decoding || !support_0padding)
232: 		ret = LZ4_decompress_safe_partial(src + inputmargin, out,
233: 				rq->inputsize, rq->outputsize, rq->outputsize);
234: 	else
235: 		ret = LZ4_decompress_safe(src + inputmargin, out,
236: 					  rq->inputsize, rq->outputsize);
237: 
238: 	if (ret != rq->outputsize) {
239: 		erofs_err(rq->sb, "failed to decompress %d in[%u, %u] out[%u]",
240: 			  ret, rq->inputsize, inputmargin, rq->outputsize);
241: 
242: 		print_hex_dump(KERN_DEBUG, "[ in]: ", DUMP_PREFIX_OFFSET,
243: 			       16, 1, src + inputmargin, rq->inputsize, true);
244: 		print_hex_dump(KERN_DEBUG, "[out]: ", DUMP_PREFIX_OFFSET,
245: 			       16, 1, out, rq->outputsize, true);
246: 
247: 		if (ret >= 0)
248: 			memset(out + ret, 0, rq->outputsize - ret);
249: 		ret = -EIO;
250: 	}
251: 
252: 	if (maptype == 0) {
253: 		kunmap_atomic(src);
254: 	} else if (maptype == 1) {
255: 		vm_unmap_ram(src, PAGE_ALIGN(rq->inputsize) >> PAGE_SHIFT);
256: 	} else if (maptype == 2) {
257: 		erofs_put_pcpubuf(src);
258: 	} else if (maptype != 3) {
259: 		DBG_BUGON(1);
260: 		return -EFAULT;
261: 	}
262: 	return ret;
263: }
