276: static void copy_from_pcpubuf(struct page **out, const char *dst,
277: 			      unsigned short pageofs_out,
278: 			      unsigned int outputsize)
279: {
280: 	const char *end = dst + outputsize;
281: 	const unsigned int righthalf = PAGE_SIZE - pageofs_out;
282: 	const char *cur = dst - pageofs_out;
283: 
284: 	while (cur < end) {
285: 		struct page *const page = *out++;
286: 
287: 		if (page) {
288: 			char *buf = kmap_atomic(page);
289: 
290: 			if (cur >= dst) {
291: 				memcpy(buf, cur, min_t(uint, PAGE_SIZE,
292: 						       end - cur));
293: 			} else {
294: 				memcpy(buf + pageofs_out, cur + pageofs_out,
295: 				       min_t(uint, righthalf, end - cur));
296: 			}
297: 			kunmap_atomic(buf);
298: 		}
299: 		cur += PAGE_SIZE;
300: 	}
301: }
