303: static int z_erofs_decompress_generic(struct z_erofs_decompress_req *rq,
304: 				      struct list_head *pagepool)
305: {
306: 	const unsigned int nrpages_out =
307: 		PAGE_ALIGN(rq->pageofs_out + rq->outputsize) >> PAGE_SHIFT;
308: 	const struct z_erofs_decompressor *alg = decompressors + rq->alg;
309: 	unsigned int dst_maptype;
310: 	void *dst;
311: 	int ret;
312: 
313: 	/* two optimized fast paths only for non bigpcluster cases yet */
314: 	if (rq->inputsize <= PAGE_SIZE) {
315: 		if (nrpages_out == 1 && !rq->inplace_io) {
316: 			DBG_BUGON(!*rq->out);
317: 			dst = kmap_atomic(*rq->out);
318: 			dst_maptype = 0;
319: 			goto dstmap_out;
320: 		}
321: 
322: 		/*
323: 		 * For the case of small output size (especially much less
324: 		 * than PAGE_SIZE), memcpy the decompressed data rather than
325: 		 * compressed data is preferred.
326: 		 */
327: 		if (rq->outputsize <= PAGE_SIZE * 7 / 8) {
328: 			dst = erofs_get_pcpubuf(1);
329: 			if (IS_ERR(dst))
330: 				return PTR_ERR(dst);
331: 
332: 			rq->inplace_io = false;
333: 			ret = alg->decompress(rq, dst);
334: 			if (!ret)
335: 				copy_from_pcpubuf(rq->out, dst, rq->pageofs_out,
336: 						  rq->outputsize);
