196: static int z_erofs_lz4_decompress(struct z_erofs_decompress_req *rq, u8 *dst)
197: {
198: 	unsigned int inputmargin;
199: 	u8 *out, *headpage, *src;
200: 	bool support_0padding;
201: 	int ret, maptype;
202: 
203: 	DBG_BUGON(*rq->in == NULL);
204: 	headpage = kmap_atomic(*rq->in);
205: 	inputmargin = 0;
206: 	support_0padding = false;
207: 
208: 	/* decompression inplace is only safe when 0padding is enabled */
209: 	if (erofs_sb_has_lz4_0padding(EROFS_SB(rq->sb))) {
210: 		support_0padding = true;
211: 
212: 		while (!headpage[inputmargin & ~PAGE_MASK])
213: 			if (!(++inputmargin & ~PAGE_MASK))
214: 				break;
215: 
216: 		if (inputmargin >= rq->inputsize) {
217: 			kunmap_atomic(headpage);
218: 			return -EIO;
219: 		}
220: 	}
221: 
222: 	rq->inputsize -= inputmargin;
223: 	src = z_erofs_handle_inplace_io(rq, headpage, dst, &inputmargin,
224: 					&maptype, support_0padding);
225: 	if (IS_ERR(src))
226: 		return PTR_ERR(src);
227: 
228: 	out = dst + rq->pageofs_out;
229: 	/* legacy format could compress extra data in a pcluster. */
230: 	if (rq->partial_decoding || !support_0padding)
231: 		ret = LZ4_decompress_safe_partial(src + inputmargin, out,
232: 				rq->inputsize, rq->outputsize, rq->outputsize);
233: 	else
234: 		ret = LZ4_decompress_safe(src + inputmargin, out,
235: 					  rq->inputsize, rq->outputsize);
236: 
237: 	if (ret != rq->outputsize) {
238: 		erofs_err(rq->sb, "failed to decompress %d in[%u, %u] out[%u]",
239: 			  ret, rq->inputsize, inputmargin, rq->outputsize);
240: 
241: 		print_hex_dump(KERN_DEBUG, "[ in]: ", DUMP_PREFIX_OFFSET,
242: 			       16, 1, src + inputmargin, rq->inputsize, true);
243: 		print_hex_dump(KERN_DEBUG, "[out]: ", DUMP_PREFIX_OFFSET,
244: 			       16, 1, out, rq->outputsize, true);
245: 
246: 		if (ret >= 0)
247: 			memset(out + ret, 0, rq->outputsize - ret);
248: 		ret = -EIO;
249: 	}
250: 
251: 	if (maptype == 0) {
252: 		kunmap_atomic(src);
253: 	} else if (maptype == 1) {
254: 		vm_unmap_ram(src, PAGE_ALIGN(rq->inputsize) >> PAGE_SHIFT);
255: 	} else if (maptype == 2) {
256: 		erofs_put_pcpubuf(src);
257: 	} else if (maptype != 3) {
258: 		DBG_BUGON(1);
259: 		return -EFAULT;
260: 	}
261: 	return ret;
262: }
